    parent.path != ""

    # Get all conditional statements in the parent
    conditions := glitch_lib.all_conditional_statements(parent)

    # Find top-level conditional statements (SWITCH or IF types)
    top_cond := conditions[_]
    top_cond.is_top == true
    top_cond.type == 2  # SWITCH type

    # Check if this conditional has multiple explicit cases by walking through else_statement chain
    # We'll check up to 5 levels deep to avoid infinite recursion
    chain_has_multiple_cases := false
    chain_has_default := false

    # First level
    current := top_cond
    case_count := 0
    default_found := false

    # Count non-default cases in the chain
    if current.is_default == false {
        case_count := case_count + 1
    }
    if current.is_default == true {
        default_found := true
    }

    # Check else_statement chain up to 5 levels
    current_1 := current.else_statement
    if current_1 != null {
        if current_1.ir_type == "ConditionalStatement" {
            if current_1.is_default == false {
                case_count := case_count + 1
            }
            if current_1.is_default == true {
                default_found := true
            }

            current_2 := current_1.else_statement
            if current_2 != null {
                if current_2.ir_type == "ConditionalStatement" {
                    if current_2.is_default == false {
                        case_count := case_count + 1
                    }
                    if current_2.is_default == true {
                        default_found := true
                    }

                    current_3 := current_2.else_statement
                    if current_3 != null {
                        if current_3.ir_type == "ConditionalStatement" {
                            if current_3.is_default == false {
                                case_count := case_count + 1
                            }
                            if current_3.is_default == true {
                                default_found := true
                            }

                            current_4 := current_3.else_statement
                            if current_4 != null {
                                if current_4.ir_type == "ConditionalStatement" {
                                    if current_4.is_default == false {
                                        case_count := case_count + 1
                                    }
                                    if current_4.is_default == true {
                                        default_found := true
                                    }

                                    current_5 := current_4.else_statement
                                    if current_5 != null {
                                        if current_5.ir_type == "ConditionalStatement" {
                                            if current_5.is_default == false {
                                                case_count := case_count + 1
                                            }
                                            if current_5.is_default == true {
                                                default_found := true
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    # Check if there are multiple explicit cases and no default
    case_count >= 2
    default_found == false

    result := {
